using System.Collections.Generic;
using UnityEngine;

namespace Apex.Game
{
    /// <summary>
    /// Material registry. Prefers material assets generated by the editor setup
    /// (Resources/ApexMaterials, guaranteed to be included in builds); otherwise
    /// creates materials at runtime from the URP Lit shader (editor play mode) or
    /// the built-in Standard shader as a last resort.
    /// </summary>
    public static class ApexMaterials
    {
        public const string ResourceFolder = "ApexMaterials";

        public static readonly Dictionary<string, Color> Palette = new Dictionary<string, Color>
        {
            ["Asphalt"] = new Color(0.22f, 0.22f, 0.24f),
            ["Line"] = new Color(0.92f, 0.92f, 0.92f),
            ["PitLane"] = new Color(0.3f, 0.3f, 0.32f),
            ["KerbRed"] = new Color(0.78f, 0.1f, 0.08f),
            ["KerbWhite"] = new Color(0.94f, 0.94f, 0.94f),
            ["Grass"] = new Color(0.3f, 0.47f, 0.19f),
            ["Wall"] = new Color(0.72f, 0.73f, 0.75f),
            ["WallStripe"] = new Color(0.12f, 0.55f, 0.75f),
            ["Ground"] = new Color(0.36f, 0.42f, 0.27f),
            ["Water"] = new Color(0.16f, 0.32f, 0.42f),
            ["Building"] = new Color(0.82f, 0.74f, 0.62f),
            ["Roof"] = new Color(0.55f, 0.24f, 0.18f),
            ["CarPaint"] = new Color(0.05f, 0.33f, 0.62f),
            ["CarAccent"] = new Color(0.1f, 0.85f, 0.95f),
            ["Carbon"] = new Color(0.06f, 0.06f, 0.07f),
            ["Tire"] = new Color(0.04f, 0.04f, 0.04f),
            ["Rim"] = new Color(0.55f, 0.56f, 0.6f),
            ["Helmet"] = new Color(0.92f, 0.92f, 0.95f),
            ["Steel"] = new Color(0.2f, 0.22f, 0.25f),
            ["Marker"] = new Color(0.95f, 0.8f, 0.1f),
        };

        static readonly Dictionary<string, (float smoothness, float metallic)> Surface = new Dictionary<string, (float, float)>
        {
            ["CarPaint"] = (0.8f, 0.2f),
            ["CarAccent"] = (0.7f, 0.1f),
            ["Carbon"] = (0.55f, 0.2f),
            ["Rim"] = (0.7f, 0.85f),
            ["Steel"] = (0.6f, 0.6f),
            ["Water"] = (0.9f, 0f),
            ["Helmet"] = (0.85f, 0.1f),
        };

        static readonly Dictionary<string, Material> Cache = new Dictionary<string, Material>();

        public static Material Get(string key)
        {
            if (Cache.TryGetValue(key, out var m) && m != null) return m;
            m = Resources.Load<Material>(ResourceFolder + "/" + key);
            if (m == null) m = Create(key);
            Cache[key] = m;
            return m;
        }

        public static Shader LitShader()
        {
            var s = Shader.Find("Universal Render Pipeline/Lit");
            if (s == null) s = Shader.Find("Standard");
            return s;
        }

        /// <summary>Creates a material for a palette key (also used by the editor setup).</summary>
        public static Material Create(string key)
        {
            var mat = new Material(LitShader()) { name = "Apex_" + key };
            var color = Palette.TryGetValue(key, out var c) ? c : Color.magenta;
            if (mat.HasProperty("_BaseColor")) mat.SetColor("_BaseColor", color);
            if (mat.HasProperty("_Color")) mat.SetColor("_Color", color);
            var (smooth, metal) = Surface.TryGetValue(key, out var sm) ? sm : (0.25f, 0f);
            if (mat.HasProperty("_Smoothness")) mat.SetFloat("_Smoothness", smooth);
            if (mat.HasProperty("_Glossiness")) mat.SetFloat("_Glossiness", smooth);
            if (mat.HasProperty("_Metallic")) mat.SetFloat("_Metallic", metal);
            mat.enableInstancing = true;
            return mat;
        }
    }
}
